import java.nio.file.*;import java.util.*;import javax.tools.*;import javax.lang.model.element.*;import javax.lang.model.type.*;import com.sun.source.tree.*;import com.sun.source.util.*;
/** Source positions and actual javac symbols; errors retained, never a whole-mod success claim. */
public class ItemTooltipScanner {
 static String b(Object s){return Base64.getEncoder().encodeToString(String.valueOf(s).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 public static void main(String[] args)throws Exception {
 JavaCompiler c=ToolProvider.getSystemJavaCompiler();DiagnosticCollector<JavaFileObject>d=new DiagnosticCollector<>();StandardJavaFileManager f=c.getStandardFileManager(d,null,null);
 JavacTask t=(JavacTask)c.getTask(null,f,d,Arrays.asList("-proc:none","-source","8","-classpath",args[1],"-Xmaxerrs","100000"),null,f.getJavaFileObjectsFromStrings(Files.readAllLines(Paths.get(args[0]))));Trees trees=Trees.instance(t);List<CompilationUnitTree> us=new ArrayList<>();for(CompilationUnitTree u:t.parse())us.add(u);t.analyze();
 for(CompilationUnitTree u:us){String s=u.getSourceFile().getCharContent(true).toString();String file=Paths.get(u.getSourceFile().toUri()).toString();new TreePathScanner<Void,Void>(){
 long start(Tree x){return trees.getSourcePositions().getStartPosition(u,x);}long end(Tree x){return trees.getSourcePositions().getEndPosition(u,x);}String text(Tree x){return start(x)<0||end(x)<start(x)?"":s.substring((int)start(x),(int)end(x));}
 public Void visitClass(ClassTree n,Void v){Element e=trees.getElement(getCurrentPath());if(e instanceof TypeElement){TypeElement a=(TypeElement)e;List<String> anc=new ArrayList<>();while(a!=null){anc.add(a.getQualifiedName().toString());TypeMirror p=a.getSuperclass();a=p.getKind()==TypeKind.DECLARED?(TypeElement)t.getTypes().asElement(p):null;}System.out.println("CLASS\t"+file+"\t"+b(e)+"\t"+b(String.join(";",anc)));}return super.visitClass(n,v);}
 public Void visitMethod(MethodTree n,Void v){if(n.getName().contentEquals("addInformation")){Element e=trees.getElement(getCurrentPath());List<String> params=new ArrayList<>();for(VariableTree p:n.getParameters())params.add(p.getType()+" "+p.getName());List<String> refs=new ArrayList<>();if(n.getBody()!=null)new TreePathScanner<Void,Void>(){public Void visitIdentifier(IdentifierTree x,Void z){Element q=trees.getElement(getCurrentPath());if(q!=null&&q.getKind()==ElementKind.PARAMETER)refs.add(q.getSimpleName().toString());return super.visitIdentifier(x,z);}}.scan(new TreePath(getCurrentPath(),n.getBody()),null);System.out.println("METHOD\t"+file+"\t"+start(n)+"\t"+end(n)+"\t"+b(e==null?null:e.getEnclosingElement())+"\t"+b(String.join(";",params))+"\t"+b(String.join(";",refs))+"\t"+b(n.getBody()==null?"":text(n.getBody()))+"\t"+b(text(n)));}return super.visitMethod(n,v);}
 public Void visitMethodInvocation(MethodInvocationTree n,Void v){ExpressionTree x=n.getMethodSelect();String name=x instanceof MemberSelectTree?((MemberSelectTree)x).getIdentifier().toString():x.toString();if(name.equals("addInformation")){Element e=trees.getElement(getCurrentPath());System.out.println("CALL\t"+file+"\t"+start(n)+"\t"+b(e instanceof ExecutableElement?e.getEnclosingElement()+":"+e:"unresolved")+"\t"+b(text(n)));}return super.visitMethodInvocation(n,v);}
 }.scan(u,null);}
 long errors=0;for(Diagnostic<? extends JavaFileObject> x:d.getDiagnostics())if(x.getKind()==Diagnostic.Kind.ERROR){errors++;System.err.println((x.getSource()==null?"":x.getSource().getName())+":"+x.getLineNumber()+":"+x.getCode()+":"+x.getMessage(Locale.ROOT).replace('\n',' '));}System.err.println("ERRORS="+errors+" (incomplete attribution, not successful mod compilation)");
 }
}
